<?php
if (!defined('ABSPATH')) { exit; }
class RC_Admin {
    public static function init(){ add_action('admin_menu',[__CLASS__,'menu']); add_action('admin_post_rc_save_asset',[__CLASS__,'save_asset']); add_action('admin_post_rc_save_settings',[__CLASS__,'save_settings']); add_action('admin_post_rc_export_waitlist',[__CLASS__,'export_waitlist']); }
    public static function menu(){ add_menu_page('ReserveChain','ReserveChain','manage_options','reservechain',[__CLASS__,'overview'],'dashicons-shield-alt',3); add_submenu_page('reservechain','Asset Programs','Asset Programs','rc_edit_assets','rc-assets',[__CLASS__,'assets']); add_submenu_page('reservechain','Waitlist','Waitlist','rc_manage_waitlist','rc-waitlist',[__CLASS__,'waitlist']); add_submenu_page('reservechain','Audit Log','Audit Log','rc_view_audit','rc-audit',[__CLASS__,'audit']); add_submenu_page('reservechain','Settings','Settings','manage_options','rc-settings',[__CLASS__,'settings']); }
    private static function wrap($title,$body){echo '<div class="wrap"><h1>'.esc_html($title).'</h1>'.$body.'</div>';}
    public static function overview(){ global $wpdb; $a=count(RC_Registry::all_public()); $w=(int)$wpdb->get_var('SELECT COUNT(*) FROM '.RC_Waitlist::table()); $ok=RC_Audit::verify_chain(); self::wrap('ReserveChain Control Center','<p><strong>Mode:</strong> '.esc_html(strtoupper(get_option('rc_mode','prelaunch'))).'</p><p><strong>Published asset programs:</strong> '.$a.'</p><p><strong>Waitlist registrations:</strong> '.$w.'</p><p><strong>Audit chain:</strong> '.($ok?'<span style="color:green">VALID</span>':'<span style="color:red">INVALID</span>').'</p><p>This admin area is intentionally pre-launch safe. Live token purchase, payment and redemption actions are not implemented or exposed.</p>'); }
    public static function assets(){ global $wpdb; $rows=$wpdb->get_results('SELECT * FROM '.RC_Registry::table().' ORDER BY id',ARRAY_A); ob_start(); foreach($rows as $r){ ?><hr><h2><?php echo esc_html($r['name']); ?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('rc_save_asset_'.$r['id']); ?><input type="hidden" name="action" value="rc_save_asset"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><table class="form-table"><tr><th>Purity</th><td><input name="purity" value="<?php echo esc_attr($r['purity']); ?>"></td></tr><tr><th>Diameter</th><td><input name="diameter" value="<?php echo esc_attr($r['diameter']); ?>"></td></tr><tr><th>Verification status</th><td><input class="regular-text" name="verification_status" value="<?php echo esc_attr($r['verification_status']); ?>"></td></tr><tr><th>Custody status</th><td><input class="regular-text" name="custody_status" value="<?php echo esc_attr($r['custody_status']); ?>"></td></tr><tr><th>Reserve status</th><td><input class="regular-text" name="reserve_status" value="<?php echo esc_attr($r['reserve_status']); ?>"></td></tr><tr><th>Tokenization status</th><td><input class="regular-text" name="tokenization_status" value="<?php echo esc_attr($r['tokenization_status']); ?>"></td></tr><tr><th>Publication state</th><td><select name="publication_state"><?php foreach(['draft','under_review','approved','published','unpublished','archived'] as $s)echo '<option '.selected($r['publication_state'],$s,false).'>'.esc_html($s).'</option>'; ?></select></td></tr><tr><th>Reason for change</th><td><input class="regular-text" name="reason" required></td></tr></table><?php submit_button('Save with audit record'); ?></form><?php } self::wrap('Asset Programs',ob_get_clean()); }
    public static function save_asset(){ if(!current_user_can('rc_edit_assets'))wp_die('Forbidden'); $id=(int)($_POST['id']??0); check_admin_referer('rc_save_asset_'.$id); $fields=[]; foreach(['purity','diameter','verification_status','custody_status','reserve_status','tokenization_status','publication_state'] as $k)$fields[$k]=wp_unslash($_POST[$k]??''); RC_Registry::update($id,$fields,sanitize_text_field(wp_unslash($_POST['reason']??''))); wp_safe_redirect(admin_url('admin.php?page=rc-assets&updated=1')); exit; }
    public static function waitlist(){ $rows=RC_Waitlist::all(); ob_start(); ?><p><a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=rc_export_waitlist'),'rc_export_waitlist')); ?>">Export CSV</a></p><table class="widefat striped"><thead><tr><th>Name</th><th>Email</th><th>Country</th><th>Type</th><th>Interest</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo esc_html($r['first_name'].' '.$r['last_name']); ?></td><td><?php echo esc_html($r['email']); ?></td><td><?php echo esc_html($r['country']); ?></td><td><?php echo esc_html($r['participant_type']); ?></td><td><?php echo esc_html($r['material_interest']); ?></td><td><?php echo esc_html($r['subscription_status']); ?></td><td><?php echo esc_html($r['created_at']); ?></td></tr><?php endforeach; ?></tbody></table><?php self::wrap('Waitlist',ob_get_clean()); }
    public static function export_waitlist(){ if(!current_user_can('rc_manage_waitlist'))wp_die('Forbidden'); check_admin_referer('rc_export_waitlist'); $rows=RC_Waitlist::all(); nocache_headers(); header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename=reservechain-waitlist.csv'); $o=fopen('php://output','w'); fputcsv($o,array_keys($rows[0]??['status'=>'no records'])); foreach($rows as $r)fputcsv($o,$r); fclose($o); exit; }
    public static function audit(){ global $wpdb; $rows=$wpdb->get_results('SELECT * FROM '.RC_Audit::table().' ORDER BY id DESC LIMIT 200',ARRAY_A); ob_start(); ?><p>Hash chain status: <strong><?php echo RC_Audit::verify_chain()?'VALID':'INVALID'; ?></strong></p><table class="widefat striped"><thead><tr><th>ID</th><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Hash</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo (int)$r['id']; ?></td><td><?php echo esc_html($r['created_at']); ?></td><td><?php echo (int)$r['actor_user_id']; ?></td><td><?php echo esc_html($r['action']); ?></td><td><?php echo esc_html($r['record_type'].'/'.$r['record_id']); ?></td><td><code><?php echo esc_html(substr($r['event_hash'],0,16)); ?>…</code></td></tr><?php endforeach; ?></tbody></table><?php self::wrap('Append-Only Audit Log',ob_get_clean()); }
    public static function settings(){ $mode=get_option('rc_mode','prelaunch'); ob_start(); ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('rc_save_settings'); ?><input type="hidden" name="action" value="rc_save_settings"><table class="form-table"><tr><th>Website mode</th><td><select name="rc_mode"><?php foreach(['development','prelaunch','waitlist','documentation_release','asset_verification','eligibility','early_participation','live_offering','redemption','enterprise_onboarding'] as $m)echo '<option '.selected($mode,$m,false).'>'.esc_html($m).'</option>'; ?></select><p class="description">Live offering and redemption modes require RC_ALLOW_LIVE_MODE=true in wp-config.php in addition to this setting.</p></td></tr><tr><th>Corporate status</th><td><input class="large-text" name="rc_corporate_status" value="<?php echo esc_attr(get_option('rc_corporate_status')); ?>"></td></tr><tr><th>Mandatory disclosure</th><td><textarea class="large-text" rows="6" name="rc_mandatory_disclosure"><?php echo esc_textarea(get_option('rc_mandatory_disclosure')); ?></textarea></td></tr></table><?php submit_button('Save settings'); ?></form><?php self::wrap('ReserveChain Settings',ob_get_clean()); }
    public static function save_settings(){ if(!current_user_can('manage_options'))wp_die('Forbidden'); check_admin_referer('rc_save_settings'); $before=['mode'=>get_option('rc_mode'),'corporate_status'=>get_option('rc_corporate_status'),'disclosure'=>get_option('rc_mandatory_disclosure')]; $mode=sanitize_key($_POST['rc_mode']??'prelaunch'); if(in_array($mode,['live_offering','redemption'],true)&&!(defined('RC_ALLOW_LIVE_MODE')&&RC_ALLOW_LIVE_MODE))$mode='prelaunch'; update_option('rc_mode',$mode); update_option('rc_corporate_status',sanitize_text_field(wp_unslash($_POST['rc_corporate_status']??''))); update_option('rc_mandatory_disclosure',sanitize_textarea_field(wp_unslash($_POST['rc_mandatory_disclosure']??''))); $after=['mode'=>$mode,'corporate_status'=>get_option('rc_corporate_status'),'disclosure'=>get_option('rc_mandatory_disclosure')]; RC_Audit::append('settings_updated','settings','global',$before,$after,'Administrative settings update'); wp_safe_redirect(admin_url('admin.php?page=rc-settings&updated=1')); exit; }
}
